// ============ EMBEDDED GLB ASSETS (CC0, Kenney) ============
'use strict';
const GLB_ASSETS_B64 = {
  SOLDIER: "",
  TREE: "",
  CRATE: "",
  COLUMN: "",
  BARREL: "",
};

// per-kit colormap data URIs (GLBs reference Textures/colormap.png
// externally, which file:// pages cannot fetch)
const TEX_COLORMAP_MINI_ARENA = "data:image/png;base64,";
const TEX_COLORMAP_SURVIVAL = "data:image/png;base64,";


function glbToArrayBuffer(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes.buffer;
}
const GLB_PARSED = {};   // name -> gltf (scene + animations)
// Which colormap a given asset's "Textures/colormap.png" refers to (per kit).
const GLB_COLORMAP = {
  SOLDIER: TEX_COLORMAP_MINI_ARENA,
  TREE: TEX_COLORMAP_MINI_ARENA,
  CRATE: TEX_COLORMAP_MINI_ARENA,
  COLUMN: TEX_COLORMAP_MINI_ARENA,
  BARREL: TEX_COLORMAP_SURVIVAL
};
function loadEmbeddedAssets(onProgress) {
  const names = Object.keys(GLB_ASSETS_B64);
  let loaded = 0;
  return Promise.all(names.map(function (name) {
    return new Promise(function (resolve) {
      // one manager per asset so each kit remaps colormap.png to its own texture
      const manager = new THREE.LoadingManager();
      manager.setURLModifier(function (url) {
        if (url.indexOf('colormap') >= 0) return GLB_COLORMAP[name];
        return url;
      });
      const loader = new THREE.GLTFLoader(manager);
      loader.parse(glbToArrayBuffer(GLB_ASSETS_B64[name]), '', function (gltf) {
        GLB_PARSED[name] = gltf;
        loaded++;
        if (onProgress) onProgress(name, loaded, names.length);
        resolve(true);
      }, function (err) {
        console.warn('GLB parse failed for', name, err);
        loaded++;
        if (onProgress) onProgress(name, loaded, names.length);
        resolve(false);
      });
    });
  }));
}

